    TwistExpander_Arcturus_Arx::KEY_B_A(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_B(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_C(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_D(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_E(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_F(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_G(PARAMS_SEED);

    TwistExpander_Arcturus_Arx::KEY_B_H(PARAMS_SEED);

    TwistSquash::SquashC(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);

    GrowKeyA(pWorkSpace, ARX_STATE_VARS);

    FoldKeyRowA(pWorkSpace);

    GrowKeyB(pWorkSpace, ARX_STATE_VARS);

    FoldKeyRowB(pWorkSpace);

    pWorkSpace->Zero_PostSeed();

    Zero_PostSeed();
